SELECT id, job_title, salary, hire_date, level, ROUND(salary / SUM(salary) OVER (PARTITION BY level), 4) salary_share, ROW_NUMBER() OVER (PARTITION BY level, manager_id ORDER BY salary DESC, id) seq_no, ROW_NUMBER() OVER (PARTITION BY job_title ORDER BY hire_date DESC, id) event_seq, AVG(salary) OVER w_hist salary_avg_5_prior, SUM(salary) OVER (PARTITION BY manager_id ORDER BY salary, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_salary FROM employees WINDOW w_hist AS (PARTITION BY job_title ORDER BY salary, id ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING);
